    templates:[{id:'t1',name:'mansam_floral_collection',label:'Floral collection',category:'Marketing',language:'English',body:'Discover three floral fragrances from Mansam. Swipe to find your favourite and explore the collection.',button:'Shop now',image:true,status:'Approved'},{id:'t2',name:'shop_now',label:'Your next signature scent',category:'Marketing',language:'English',body:'Find a fragrance that feels like you. Discover the latest from Mansam and make every moment memorable.',button:'Explore collection',image:false,status:'Approved'},{id:'t3',name:'payment_sucessfull',label:'Payment received',category:'Utility',language:'English (US)',body:'Thank you, {{1}}. We have received your payment for order {{2}}. Your receipt is ready.',button:'View receipt',image:false,status:'Approved'}],
