  function load(){if(SaaS?.enabled)return SaaS.state||seed();try{const data=JSON.parse(localStorage.getItem(STORAGE_KEY));if(data?.settings&&Array.isArray(data.contacts)&&Array.isArray(data.templates)) return data;}catch{}return seed();}
  let db=load(), route='dashboard', selectedChat='c1', contactQuery='', contactFilter='All contacts', chatQuery='', settingsTab='business', campaignFilter='All campaigns', metricRange='7 days', storageWarning=false;
  function persist(){if(SaaS?.enabled){if(SaaS.account)return SaaS.save(db);return;}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Changes will last for this session only.');}}}
  let toastTimer;
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
  const pages=[['dashboard','Overview'],['inbox','Inbox'],['contacts','Contacts'],['pipelines','Sales pipeline'],['broadcasts','Campaigns'],['templates','Templates'],['automations','Automations'],['flows','Flow builder'],['agents','AI assistant'],['subscribers','Subscribers'],['reports','Reports'],['notifications','Notifications'],['settings','Settings'],...(SaaS?.enabled?[['branding','Brand identity'],['team','Team members'],['billing','Plans & billing'],['audit','Audit history'],['integrations','Integrations'],['security','Account & security']]:[])];
